// RequirementDetail.jsx
import React from 'react';
import './RequirementDetail.css';

const RequirementDetail = ({ requirement, onBack }) => {
  if (!requirement) return null;

  return (
    <div className="main-content">
      {/* Back button */}
      <button className="back-button" onClick={onBack}>
        <i className="fas fa-arrow-left"></i>
        BACK TO LEDGER
      </button>

      {/* Header section */}
      <div className="detail-header">
        <div className="detail-citation">
          {requirement.citation}
        </div>
        <div className="detail-category">
          {requirement.category.toUpperCase()}
        </div>
      </div>

      {/* Title */}
      <h1 className="detail-title">{requirement.description}</h1>

      {/* Regulation rule */}
      <div className="detail-regulation">
        <div className="regulation-label">REGULATION RULE</div>
        <div className="regulation-text">
          {requirement.frequency_rule || 'Annually, per RRC-assigned schedule'}
        </div>
        <button className="regulation-link">
          <i className="fas fa-file-alt"></i>
          Read Full Regulation Text
        </button>
      </div>

      {/* Action Panel */}
      <div className="detail-action-panel">
        <div className="action-label">ACTION PANEL</div>
        <button className="action-button complete">
          <i className="fas fa-check-circle"></i>
          MARK COMPLETE
        </button>
        <button className="action-button dispatch">
          <i className="fas fa-truck"></i>
          DISPATCH VENDOR
        </button>
      </div>

      {/* Timeline */}
      <div className="detail-timeline">
        <div className="timeline-label">TIMELINE</div>
        <div className="timeline-grid">
          <div className="timeline-item">
            <span className="timeline-sub">NEXT DUE</span>
            <span className="timeline-value">{requirement.due}</span>
          </div>
          <div className="timeline-item">
            <span className="timeline-sub">LAST COMPLETED</span>
            <span className="timeline-value">
              {requirement.last_completed || 'Jul 12, 2026'}
            </span>
          </div>
        </div>
      </div>

      {/* Assignment */}
      <div className="detail-assignment">
        <div className="assignment-label">ASSIGNMENT</div>
        <div className="assignment-content">
          <span className="assignment-sub">CURRENT OWNER</span>
          <span className="assignment-value">
            {requirement.assigned || 'Unassigned'}
          </span>
        </div>
      </div>
    </div>
  );
};

export default RequirementDetail;
